    # === K2 Wort-Alternativen beim Eintippen (Ajdin K2, 20.11.2026, Version 1.5) ===
    # Alle tippbaren Einträge (4.469 Wörter, 297 Lückensätze) in acht Stücken
    # durchgesehen (Release\Wortschatz\k2_2026-11-20). Eindeutige Paare nach den
    # Regeln dort (gleiche Bedeutung, Standardform oder gängige bosnische Form, kein
    # Risiko), die fraglichen hat Ajdin am 20.11.2026 Karte für Karte beantwortet
    # (antworten_ajdin_2026-11-20.txt: 149 ja, 41 nein), davor „mach gleich alle
    # und lass emir direkt alle sprechen“. Die Kennung der Karte (V1-77, S-futur …)
    # steht im beleg. Wie alle Paare hier nur beim Tippen, gezeigt wird keines.
    # Die Neins bleiben falsch: GEGEN_K2 in tests/test_varianten.py und ZAEHLT_NICHT
    # in den Paket-Tests. Zwei Paare vom Nachmittag sind gestrichen (na pijaci ->
    # na tržnici, Bojim se pasa -> Plašim se pasa), weil sie „na pazaru“ und
    # „Bojim se kučadi“ gelöscht hätten; „prošle hefte“ hält ein eigenes Paar.
    # Noch nicht hier: 34 Paare für die neuen Wörter (moler, zarezač, tisućiti …),
    # sie kommen mit den Wörtern (final/varianten_final.txt, ganz unten).
    # štene -> kuče gilt nur beim Welpen (Ajdin: „kuce ist nur welpe kein
    # ausgewachsener hund“); ob die kuče-Formen beim Hund (oben, 14./15.11.)
    # bleiben, ist noch offen.
    # --- Ajdin K2, 20.11.2026: kroatisch-serbische Standardform ---
